                GrammarSection(heading: "完了・継続：just / already / yet ／ for / since", keyword: "yet",
                               chunks: [c("I", "主語", 0), c("'ve already", "have＋already", 1), c("finished", "過去分詞", 2), c("my homework", "", 3)],
                               examples: [e("I've already finished my homework.", "aɪv ɔːlɹˌɛdɪ fˈɪnɪʃt maɪ hˈəʊmwɜːk", "宿題はもう終わった。"),
                                          e("Have you eaten yet?", "hæv juː ˈiːtən jˈɛt", "もうご飯食べた？"),
