            detailTitle: "to ＋ 動詞 と 動詞 ing", detailSubtitle: "前の動詞で決まる",
            sections: [
                GrammarSection(heading: "want / need / decide / hope ＋ to 動詞", keyword: "to",
                               chunks: [c("I", "主語", 0), c("want", "動詞", 1), c("to go", "to＋動詞", 2), c("home", "", 3)],
