                               chunks: [c("I stayed home", "結果", 0), c("because", "理由", 1), c("it was raining", "原因", 2)],
                               examples: [e("I stayed home because it was raining.", "aɪ stˈeɪd hˈəʊm bɪkˈɒz ɪt wɒz ɹˈeɪnɪŋ", "雨が降っていたので家にいた。"),
